import{_ as a,o,c as n,a2 as r}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"5.8 漏电保护器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-8-lou-dian-bao-hu-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-8-lou-dian-bao-hu-qi.md","lastUpdated":1793095197000}'),s={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-8-lou-dian-bao-hu-qi.md"};function l(i,t,e,g,d,u){return o(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="_5-8-漏电保护器" tabindex="-1">5.8 漏电保护器 <a class="header-anchor" href="#_5-8-漏电保护器" aria-label="Permalink to &quot;5.8 漏电保护器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>漏电保护器(漏保)是<strong>防人身触电</strong>的&quot;最后一道防线&quot;:设备漏电或人体触电时,它能在极短时间(0.1 秒级)内切断电源。现在家庭、工地、配电箱几乎必装。这一节讲原理、参数和安装要求——这是全书<strong>五星考点</strong>。</p><h2 id="一、漏电保护器是干什么的" tabindex="-1">一、漏电保护器是干什么的 <a class="header-anchor" href="#一、漏电保护器是干什么的" aria-label="Permalink to &quot;一、漏电保护器是干什么的&quot;">​</a></h2><p><strong>漏电保护器(残余电流动作保护器)</strong>:检测电路中的<strong>漏电电流</strong>,当漏电电流达到整定值时,自动切断电源。</p><ul><li>核心作用:<strong>防止人身触电、防止漏电火灾</strong>;</li><li>与断路器分工:断路器管短路/过载,漏保管<strong>漏电(对地泄漏)</strong>——两者常做成一体(漏电断路器)。</li></ul><h2 id="二、工作原理-零序电流互感器" tabindex="-1">二、工作原理:零序电流互感器 <a class="header-anchor" href="#二、工作原理-零序电流互感器" aria-label="Permalink to &quot;二、工作原理:零序电流互感器&quot;">​</a></h2><p>漏电保护器内部有一个<strong>零序电流互感器</strong>,火线和零线同时穿过它的铁芯:</p><ul><li><strong>正常时</strong>:流过火线的电流 = 流过零线的电流,两股电流的磁场<strong>互相抵消</strong>,互感器无输出;</li><li><strong>漏电时</strong>:部分电流经漏电点(或人体)流入大地,回到零线的电流<strong>变小</strong>,火零电流不再相等,互感器检测到&quot;不平衡电流&quot;(残余电流);</li><li>当残余电流达到整定值时,推动脱扣机构<strong>跳闸断电</strong>。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常:  火线 ──► │ 电流相等,磁场抵消,不动作</span></span>
<span class="line"><span>       零线 ──► │</span></span>
<span class="line"><span>漏电:  火线 ──► ││ 电流不等 → 检测到残余电流 → 跳闸</span></span>
<span class="line"><span>       零线 ──► ││</span></span></code></pre></div><blockquote><p>💡 <strong>通俗理解</strong>:漏保在&quot;数&quot;流出去的火线电流和流回来的零线电流——两者对不上账,说明有电流&quot;漏&quot;到别处(比如人体、大地),立刻断电。</p></blockquote><h2 id="三、主要参数-必背" tabindex="-1">三、主要参数(必背) <a class="header-anchor" href="#三、主要参数-必背" aria-label="Permalink to &quot;三、主要参数(必背)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><strong>额定漏电动作电流</strong></td><td>达到该电流值即动作;<strong>家用一般选 30 mA</strong></td></tr><tr><td><strong>额定漏电不动作电流</strong></td><td>小于该电流不动作(一般为动作电流的一半)</td></tr><tr><td><strong>动作时间</strong></td><td>从漏电到跳闸的时间,一般要求 <strong>≤ 0.1 s</strong></td></tr></tbody></table><blockquote><p>💡 为什么是 30 mA、0.1 s?因为这两个数值处于<strong>人体安全界限</strong>之内——30 mA 在安全电流范围附近(结合摆脱电流 10 mA 与伤害界限),0.1 s 内断电可避免致命伤害。这就是&quot;30 mA · 0.1 s&quot;保护人身安全的由来。</p></blockquote><h2 id="四、安装与使用要求" tabindex="-1">四、安装与使用要求 <a class="header-anchor" href="#四、安装与使用要求" aria-label="Permalink to &quot;四、安装与使用要求&quot;">​</a></h2><ul><li><strong>安装位置</strong>:装在电源<strong>进户端/回路的首端</strong>,对全线进行漏电保护;</li><li><strong>分级保护</strong>:总开关处装漏电保护,分路也可各装一个(分级保护,选择性跳闸);</li><li><strong>试验检查</strong>:安装后和定期检查,<strong>按下&quot;试验按钮&quot;</strong>,确认能可靠跳闸(建议每月至少试一次);</li><li><strong>配合接地</strong>:漏电保护器要发挥防触电作用,需与<strong>保护接地(接零)系统</strong>配合使用;</li><li>漏电保护器<strong>不能代替</strong>熔断器/断路器的短路、过载保护。</li></ul><blockquote><p>⚠️ 判断题高频:漏电保护器主要防<strong>漏电和人身触电</strong>,不是专门做短路保护的。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 漏保原理:<strong>零序电流互感器</strong>检测火零电流不平衡。</li><li>✅ 家用额定漏电动作电流 <strong>30 mA</strong>,动作时间 ≤ <strong>0.1 s</strong>。</li><li>✅ 按&quot;试验按钮&quot;定期检查跳闸功能。</li><li>✅ 漏保不能代替短路/过载保护。</li><li>⚠️ 易混点:漏保(防漏电触电)vs 断路器(防短路过载),分工不同。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>漏电保护器靠&quot;火零电流不平衡&quot;检测漏电,自动跳闸。</li><li>关键参数 30 mA、0.1 s,处于人体安全界限内。</li><li>定期按试验按钮检查;与接地系统配合;不能替代短路保护。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)家用漏电保护器的额定漏电动作电流一般选用()。 A. 10 mA　B. 30 mA　C. 100 mA　D. 300 mA</li><li>(判断)漏电保护器检测到漏电后,应在 0.1 s 内切断电源。( )</li><li>(单选)漏电保护器是利用()原理工作的。 A. 电磁感应　B. 零序电流互感器　C. 双金属片　D. 热继电器</li><li>(判断)漏电保护器可以代替熔断器作短路保护。( )</li><li>(判断)漏电保护器应定期按下试验按钮,检查其是否动作可靠。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。家用漏电保护器额定漏电动作电流一般 30 mA。</li><li><strong>√</strong>。动作时间 ≤ 0.1 s。</li><li><strong>B</strong>。零序电流互感器检测火零电流不平衡。</li><li><strong>×</strong>。漏保不能代替短路/过载保护。</li><li><strong>√</strong>。试验按钮是日常检查手段。</li></ol></details>`,24)])])}const p=a(s,[["render",l]]);export{c as __pageData,p as default};
